/* Chỉ chạy trên trang Tiêm chủng. Không gắn listener/class toàn site. */
(function initTiemChungPage() {
  var root = document.querySelector('.tiem-chung-page[data-tiem-chung-root]');
  if (!root || root.getAttribute('data-tiem-chung-ready') === '1') {
    return;
  }
  root.setAttribute('data-tiem-chung-ready', '1');

  function qsAll(selector) {
    return Array.prototype.slice.call(root.querySelectorAll(selector));
  }

  function qs(selector) {
    return root.querySelector(selector);
  }

  // Progressive scroll reveal — subtle, one-time, and reduced-motion aware
  (function initTiemChungReveal() {
    var revealSelector = [
      '.hero-text > *',
      '.section-eyebrow', '.section-title', '.section-lede',
      '.intro-copy', '.intro-fact',
      '.audience-card', '.why-doctor-visual', '.why-grid',
      '.brand-break-quote', '.testimonials-heading > *', '.testimonial-card',
      '.vaccine-tab', '.vaccine-panel',
      '.price-effective', '.price-table-wrap', '.soft-cta',
      '.process-intro', '.process-goal', '.pathway-row', '.process-footnote',
      '.care-block-title', '.safety-list', '.safety-cta-box',
      '.facility-card', '.facility-warning', '.monitor-card', '.home-care-header', '.home-care-item', '.tier-card',
      '.faq-item', '.register-heading', '.register-form', '.register-support'
    ].join(',');

    var revealItems = qsAll(revealSelector);
    for (var i = 0; i < revealItems.length; i++) {
      revealItems[i].classList.add('tc-reveal');
    }

    var leftTargets = qsAll('.intro-copy, .safety-list, .register-form');
    for (var j = 0; j < leftTargets.length; j++) {
      leftTargets[j].setAttribute('data-tc-reveal', 'left');
    }
    var rightTargets = qsAll('.why-doctor-visual, .brand-break-quote, .vaccine-panel, .safety-cta-box, .register-support');
    for (var k = 0; k < rightTargets.length; k++) {
      rightTargets[k].setAttribute('data-tc-reveal', 'right');
    }

    function stagger(container, step, max) {
      if (!step) step = 70;
      if (!max) max = 420;
      var children = container.children;
      var index = 0;
      for (var c = 0; c < children.length; c++) {
        if (children[c].classList.contains('tc-reveal')) {
          children[c].style.setProperty('--tc-reveal-delay', Math.min(index * step, max) + 'ms');
          index++;
        }
      }
    }

    var staggerContainers = qsAll([
      '.hero-text', '.intro-facts', '.audience-grid', '.why-grid',
      '.vaccine-tab-list', '.process-board', '.facility-grid', '.monitor-grid', '.home-care-grid',
      '.tier-grid', '.testimonial-grid', '.faq-list'
    ].join(','));
    for (var s = 0; s < staggerContainers.length; s++) {
      stagger(staggerContainers[s]);
    }

    var sectionContainers = qsAll('.section > .container');
    for (var sc = 0; sc < sectionContainers.length; sc++) {
      var container = sectionContainers[sc];
      var headingItems = [];
      for (var hc = 0; hc < container.children.length; hc++) {
        var child = container.children[hc];
        if (child.matches && child.matches('.section-eyebrow, .section-title, .section-lede')) {
          headingItems.push(child);
        }
      }
      for (var hi = 0; hi < headingItems.length; hi++) {
        headingItems[hi].style.setProperty('--tc-reveal-delay', (hi * 80) + 'ms');
      }
    }

    function showAll() {
      for (var r = 0; r < revealItems.length; r++) {
        revealItems[r].classList.add('tc-visible');
      }
    }

    var reduceMotion = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    if (reduceMotion || !('IntersectionObserver' in window)) {
      showAll();
      return;
    }

    var observer = new IntersectionObserver(function (entries) {
      for (var e = 0; e < entries.length; e++) {
        if (!entries[e].isIntersecting) continue;
        entries[e].target.classList.add('tc-visible');
        observer.unobserve(entries[e].target);
      }
    }, { threshold: 0.12, rootMargin: '0px 0px -8% 0px' });

    for (var o = 0; o < revealItems.length; o++) {
      observer.observe(revealItems[o]);
    }
  })();

  // Vaccine tabs
  var vaccineTabs = qsAll('.vaccine-tab');
  var vaccinePanels = qsAll('.vaccine-panel');

  function activateVaccineTab(tab, bringPanelIntoView) {
    var targetId = tab.getAttribute('aria-controls') || tab.getAttribute('data-target');
    if (!targetId) return;
    var panel = qs('#' + targetId);
    if (!panel) return;

    for (var t = 0; t < vaccineTabs.length; t++) {
      var item = vaccineTabs[t];
      var isActive = item === tab;
      if (isActive) {
        item.classList.add('active');
      } else {
        item.classList.remove('active');
      }
      item.setAttribute('aria-selected', String(isActive));
      item.tabIndex = isActive ? 0 : -1;
    }

    for (var p = 0; p < vaccinePanels.length; p++) {
      var panelItem = vaccinePanels[p];
      var panelActive = panelItem === panel;
      if (panelActive) {
        panelItem.classList.add('active');
      } else {
        panelItem.classList.remove('active');
      }
      panelItem.hidden = !panelActive;
      panelItem.setAttribute('aria-hidden', String(!panelActive));
    }

    panel.classList.add('tc-visible');

    if (bringPanelIntoView && window.innerWidth <= 900) {
      window.requestAnimationFrame(function () {
        var motionReduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        var tabScroller = tab.closest ? tab.closest('.vaccine-tab-list') : null;
        if (tabScroller && root.contains(tabScroller)) {
          var tabRect = tab.getBoundingClientRect();
          var scrollerRect = tabScroller.getBoundingClientRect();
          var targetLeft = Math.max(0, tabScroller.scrollLeft + tabRect.left - scrollerRect.left);
          if (typeof tabScroller.scrollTo === 'function') {
            try {
              tabScroller.scrollTo({ left: targetLeft, behavior: motionReduce ? 'auto' : 'smooth' });
            } catch (ex) {
              tabScroller.scrollLeft = targetLeft;
            }
          } else {
            tabScroller.scrollLeft = targetLeft;
          }
        }

        if (typeof panel.scrollIntoView !== 'function') return;
        try {
          panel.scrollIntoView({ behavior: motionReduce ? 'auto' : 'smooth', block: 'start' });
        } catch (ex2) {
          panel.scrollIntoView(true);
        }
      });
    }
  }

  for (var vt = 0; vt < vaccineTabs.length; vt++) {
    (function (tab) {
      tab.addEventListener('click', function () {
        activateVaccineTab(tab, true);
      });
    })(vaccineTabs[vt]);
  }

  var initialVaccineTab = null;
  for (var vi = 0; vi < vaccineTabs.length; vi++) {
    if (vaccineTabs[vi].classList.contains('active')) {
      initialVaccineTab = vaccineTabs[vi];
      break;
    }
  }
  if (!initialVaccineTab && vaccineTabs.length > 0) {
    initialVaccineTab = vaccineTabs[0];
  }
  if (initialVaccineTab) {
    activateVaccineTab(initialVaccineTab, false);
  }

  // Mobile horizontal-list affordance
  var scrollWrappers = qsAll('[data-vaccine-scroll]');
  for (var sw = 0; sw < scrollWrappers.length; sw++) {
    (function (wrapper) {
      var scroller = wrapper.querySelector('.vaccine-tab-list');
      if (!scroller) return;

      function updateScrollHint() {
        if (!root.contains(wrapper)) return;
        var isAtEnd = scroller.scrollLeft + scroller.clientWidth >= scroller.scrollWidth - 8;
        if (isAtEnd) {
          wrapper.classList.add('tc-at-end');
        } else {
          wrapper.classList.remove('tc-at-end');
        }
      }

      scroller.addEventListener('scroll', updateScrollHint, { passive: true });
      window.addEventListener('resize', updateScrollHint);
      updateScrollHint();
    })(scrollWrappers[sw]);
  }

  // Brief anchor flash — highlight the price row when jumped to from disease card
  function flashHashRow() {
    if (!location.hash) return;
    var safeHash = location.hash.replace(/[^#a-zA-Z0-9_-]/g, '');
    if (!safeHash || safeHash === '#') return;
    var row = qs(safeHash);
    if (row && row.tagName === 'TR') {
      row.classList.add('tc-flash');
      window.setTimeout(function () {
        row.classList.remove('tc-flash');
      }, 1600);
    }
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', flashHashRow);
  } else {
    flashHashRow();
  }
  window.addEventListener('hashchange', flashHashRow);
})();

