/* Progressive reveal animations */
.tiem-chung-page .reveal {
  opacity: 0;
  translate: 0 26px;
  transition: opacity 0.72s cubic-bezier(0.22, 1, 0.36, 1), translate 0.72s cubic-bezier(0.22, 1, 0.36, 1);
  transition-delay: var(--reveal-delay, 0ms);
  will-change: opacity, translate;
}
.tiem-chung-page .reveal[data-reveal="left"] { translate: -32px 0; }
.tiem-chung-page .reveal[data-reveal="right"] { translate: 32px 0; }
.tiem-chung-page .reveal.is-visible { opacity: 1; translate: 0 0; }

@media (prefers-reduced-motion: reduce) {
  * { transition-duration: 0.01ms !important; }
  .tiem-chung-page .reveal { opacity: 1 !important; translate: 0 0 !important; transition: none !important; }
}

