  // In-page anchors — đồng bộ Lenis để không bị kéo về đầu trang sau khi cuộn
  var ANCHOR_OFFSET = 88;

  function getAnchorTargetId(rawHash) {
    if (!rawHash) return '';
    var id = rawHash.charAt(0) === '#' ? rawHash.slice(1) : rawHash;
    return id.replace(/[^a-zA-Z0-9_-]/g, '');
  }

  function scrollToPageAnchor(targetId, updateHash) {
    if (!targetId) return false;
    var target = document.getElementById(targetId);
    if (!target || !root.contains(target)) return false;

    var motionReduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    var lenis = window.__hosLenis;

    if (lenis && typeof lenis.scrollTo === 'function') {
      try {
        lenis.scrollTo(target, {
          offset: -ANCHOR_OFFSET,
          immediate: motionReduce
        });
      } catch (ex) {
        lenis.scrollTo(target, { offset: -ANCHOR_OFFSET });
      }
    } else {
      var scrollTop = window.pageYOffset || document.documentElement.scrollTop || 0;
      var top = target.getBoundingClientRect().top + scrollTop - ANCHOR_OFFSET;
      if (typeof window.scrollTo === 'function') {
        try {
          window.scrollTo({ top: top, behavior: motionReduce ? 'auto' : 'smooth' });
        } catch (ex2) {
          window.scrollTo(0, top);
        }
      } else {
        window.scrollTo(0, top);
      }
    }

    if (updateHash !== false && history && history.replaceState) {
      history.replaceState(null, '', '#' + targetId);
    }
    return true;
  }

  function parseSamePageAnchor(href) {
    if (!href || href.indexOf('#') === -1) return null;
    var link = document.createElement('a');
    link.href = href;
    var path = link.pathname || '';
    var currentPath = location.pathname || '';
    if (path !== currentPath) return null;
    return getAnchorTargetId(link.hash);
  }

  root.addEventListener('click', function (e) {
    var link = e.target;
    while (link && link !== root) {
      if (link.tagName === 'A' && link.getAttribute('href')) break;
      link = link.parentNode;
    }
    if (!link || link === root) return;
    var targetId = parseSamePageAnchor(link.getAttribute('href'));
    if (!targetId) return;
    if (scrollToPageAnchor(targetId, true)) {
      e.preventDefault();
      flashHashRow();
    }
  });

  function syncInitialHashAnchor(attempt) {
    if (!attempt) attempt = 0;
    var targetId = getAnchorTargetId(location.hash);
    if (!targetId) return;
    if (window.__hosLenis || attempt >= 40) {
      scrollToPageAnchor(targetId, false);
      flashHashRow();
      return;
    }
    window.setTimeout(function () {
      syncInitialHashAnchor(attempt + 1);
    }, 50);
  }

  // Brief anchor flash — highlight the price row when jumped to from disease card
  function flashHashRow() {
    if (!location.hash) return;
    var safeHash = location.hash.replace(/[^#a-zA-Z0-9_-]/g, '');
    if (!safeHash || safeHash === '#') return;
    var row = qs(safeHash);
    if (row && row.tagName === 'TR') {
      row.classList.add('tc-flash');
      window.setTimeout(function () {
        row.classList.remove('tc-flash');
      }, 1600);
    }
  }

  syncInitialHashAnchor(0);
  window.addEventListener('hashchange', function () {
    var targetId = getAnchorTargetId(location.hash);
    if (targetId && scrollToPageAnchor(targetId, false)) {
      flashHashRow();
    }
  });
  window.addEventListener('load', function () {
    syncInitialHashAnchor(0);
  });
})();
